import React, { useContext } from 'react';
import styles from './CartPage.module.css';
import { CartContext } from '../../context/CartContext';
import { AuthContext } from '../../context/AuthContext';

function CartPage() {
    const { cart, removeFromCart, updateQuantity, clearCart } = useContext(CartContext);
    const { token } = useContext(AuthContext);

    const total = cart.reduce((sum, item) => sum + item.currentPrice * item.quantity, 0);

    const handleCheckout = async () => {
        try {
            for (const item of cart) {
                await fetch('http://localhost:5000/api/purchases', {
                    method: 'POST',
                    headers: {
                        'Content-Type': 'application/json',
                        Authorization: `Bearer ${token}`
                    },
                    body: JSON.stringify({
                        product: item._id,
                        quantity: item.quantity,
                        purchasePrice: item.currentPrice
                    })
                });
            }
            alert('Заказ оформлен!');
            clearCart();
        } catch {
            alert('Ошибка оформления заказа');
        }
    };

    return (
        <div className={styles.cart}>
            <h2>Корзина</h2>
            {cart.length === 0 ? (
                <p>Корзина пуста</p>
            ) : (
                <>
                    <ul>
                        {cart.map(item => (
                            <li key={item._id}>
                                {item.name} — {item.currentPrice} ₽ ×
                                <input
                                    type="number"
                                    min="1"
                                    value={item.quantity}
                                    onChange={(e) => updateQuantity(item._id, parseInt(e.target.value))}
                                />
                                <button onClick={() => removeFromCart(item._id)}>Удалить</button>
                            </li>
                        ))}
                    </ul>
                    <p><strong>Итого:</strong> {total} ₽</p>
                    <button onClick={handleCheckout}>Оформить заказ</button>
                </>
            )}
        </div>
    );
}

export default CartPage;
